namespace sv_4a66dc5e605545e881bd57ec5cae6c3c.Client;

public sealed class UserInfo
{
    public required string Email { get; init; }
    public required string[] Roles { get; init; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_4a66dc5e605545e881bd57ec5cae6c3c.Client;

/// <summary>
/// Reads the persisted <see cref="UserInfo"/> from the server-rendered page
/// and exposes it as the authentication state on the WebAssembly client.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState state)
    {
        if (!state.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) || userInfo is null)
        {
            _authenticationStateTask = _unauthenticated;
            return;
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, userInfo.Email),
            new(ClaimTypes.Email, userInfo.Email),
        };

        foreach (var role in userInfo.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        _authenticationStateTask = Task.FromResult(
            new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(claims, "PersistentAuth"))));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authenticationStateTask;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using sv_4a66dc5e605545e881bd57ec5cae6c3c.Client;

namespace sv_4a66dc5e605545e881bd57ec5cae6c3c;

/// <summary>
/// Server-side <see cref="AuthenticationStateProvider"/> that always returns a
/// hardcoded user and persists the identity via <see cref="PersistentComponentState"/>
/// so the WebAssembly client can pick it up after interactive rendering starts.
/// </summary>
public sealed class HardcodedAuthenticationStateProvider
    : RevalidatingServerAuthenticationStateProvider
{
    private const string Email = "bob@example.com";
    private static readonly string[] Roles = ["User", "Editor"];

    private readonly PersistentComponentState _state;
    private readonly PersistingComponentStateSubscription _subscription;

    private Task<AuthenticationState>? _authenticationStateTask;

    public HardcodedAuthenticationStateProvider(
        ILoggerFactory loggerFactory,
        PersistentComponentState state)
        : base(loggerFactory)
    {
        _state = state;
        AuthenticationStateChanged += OnAuthenticationStateChanged;
        _subscription = _state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, Email),
            new(ClaimTypes.Email, Email),
        };

        foreach (var role in Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        return Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
    }

    protected override TimeSpan RevalidationInterval => TimeSpan.FromMinutes(30);

    protected override Task<bool> ValidateAuthenticationStateAsync(
        AuthenticationState authenticationState, CancellationToken cancellationToken)
    {
        return Task.FromResult(true);
    }

    private void OnAuthenticationStateChanged(Task<AuthenticationState> task)
    {
        _authenticationStateTask = task;
    }

    private async Task OnPersistingAsync()
    {
        var authState = _authenticationStateTask ??
            await GetAuthenticationStateAsync();

        var principal = authState.User;
        if (principal.Identity?.IsAuthenticated == true)
        {
            var email = principal.FindFirst(ClaimTypes.Email)?.Value ?? "";
            var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

            _state.PersistAsJson(nameof(UserInfo), new UserInfo
            {
                Email = email,
                Roles = roles,
            });
        }
    }

    protected override void Dispose(bool disposing)
    {
        _subscription.Dispose();
        AuthenticationStateChanged -= OnAuthenticationStateChanged;
        base.Dispose(disposing);
    }
}

@page "/profile"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using System.Security.Claims
@attribute [Authorize]
@rendermode InteractiveAuto

<PageTitle>Profile</PageTitle>

<h1>Profile</h1>

<AuthorizeView>
    <Authorized>
        <p><strong>Name:</strong> @context.User.Identity?.Name</p>
        <p><strong>Roles:</strong></p>
        <ul>
            @foreach (var role in context.User.FindAll(ClaimTypes.Role))
            {
                <li>@role.Value</li>
            }
        </ul>
    </Authorized>
</AuthorizeView>

@page "/editor"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize(Roles = "Editor")]
@rendermode InteractiveAuto

<PageTitle>Editor</PageTitle>

<h1>Editor</h1>

<AuthorizeView Roles="Editor">
    <Authorized>
        <p>Welcome to the editor area. You have the <strong>Editor</strong> role.</p>
    </Authorized>
    <NotAuthorized>
        <p class="text-danger">Access denied. You do not have the Editor role.</p>
    </NotAuthorized>
</AuthorizeView>

@page "/viewer"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto

<PageTitle>Viewer</PageTitle>

<h1>Viewer</h1>

<AuthorizeView>
    <Authorized>
        <p>Welcome, @context.User.Identity?.Name! This page is accessible to any authenticated user.</p>
    </Authorized>
    <NotAuthorized>
        <p class="text-danger">Access denied. You must be authenticated to view this page.</p>
    </NotAuthorized>
</AuthorizeView>

